	Policy    string
	Sensor    string
	Attach    string
	Label     string
}

type ProgOverhead struct {
	Prog
	RunTime time.Duration
	RunCnt  uint64
}

// SensorIface is an interface for sensors.Sensor that allows implementing sensors for testing.
type SensorIface interface {
	GetName() string
	IsLoaded() bool
	Load(bpfDir string) error
