		// addTracingPolicy): keeping it registered would leak one of the
		// policyfilter map slots for as long as this failed collection
		// exists.
		if filterID := policyfilter.PolicyID(col.policyfilterID); filterID != policyfilter.NoFilterID {
			h.pfState.DelPolicy(filterID)
			col.policyfilterID = uint64(policyfilter.NoFilterID)
		}
		return col.err
	}

	col.state = col.getEnabledStateType()
	return nil
